def fundamenta_pixmap(height: int = 34, dark: bool = True) -> QPixmap:
    """Devuelve el logotipo adaptado al tema (el texto es casi negro en claro)."""
    svg = FUNDAMENTA_SVG
    if dark:
        svg = svg.replace("#0f172a", "#e6ecfa").replace("#475569", "#94a3b8")
        svg = svg.replace('fill="#64748b"', 'fill="#8b94ad"')
    renderer = QSvgRenderer(QByteArray(svg.encode()))
    ratio = renderer.defaultSize().width() / max(1, renderer.defaultSize().height())
    pixmap = QPixmap(int(height * ratio * 2), height * 2)
    pixmap.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()
    pixmap.setDevicePixelRatio(2.0)
    return pixmap
